import{_ as a,a as e,b as r,c as s}from"./chunks/presets-04.Dx-DqE4-.js";import{_ as i,o,c as n,a3 as l}from"./chunks/framework.D1iekJsc.js";const P=JSON.parse('{"title":"Presets","description":"MiniTavern のプロンプトプリセット。基本プロンプトと並べ替えできる一覧で、ロールプレイの書き方を切り替えます。サンプリングはモデル設定のままです。","frontmatter":{"title":"Presets","description":"MiniTavern のプロンプトプリセット。基本プロンプトと並べ替えできる一覧で、ロールプレイの書き方を切り替えます。サンプリングはモデル設定のままです。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"Presets · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern のプロンプトプリセット。基本プロンプトと並べ替えできる一覧で、ロールプレイの書き方を切り替えます。サンプリングはモデル設定のままです。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/manual/presets"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/manual/presets"}]]},"headers":[],"relativePath":"ja/manual/presets.md","filePath":"ja/manual/presets.md","lastUpdated":1791862671000}'),p={name:"ja/manual/presets.md"};function g(c,t,h,m,d,u){return o(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to &quot;Presets&quot;">​</a></h1><p>経路：下部 <strong>設定</strong> → <strong>Presets</strong>。</p><p>プリセットは一式のプロンプト構造で、ロールプレイの書き方と制約を変えます。温度などのサンプリングはここではなく <strong>モデル設定</strong> です。</p><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+a+'" alt="設定の Presets"><figcaption>1 · 設定 → Presets</figcaption></figure><figure class="shot-step"><img src="'+e+'" alt="プリセット一覧"><figcaption>2 · 一覧と New</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="プリセットを編集"><figcaption>3 · Name、Basic prompts、Prompts</figcaption></figure><figure class="shot-step"><img src="'+s+'" alt="プロンプトを新規作成"><figcaption>4 · 新しいプロンプト</figcaption></figure></div><p>この画面のボタン名はアプリ上では英語です。</p><h2 id="一覧" tabindex="-1">一覧 <a class="header-anchor" href="#一覧" aria-label="Permalink to &quot;一覧&quot;">​</a></h2><ol><li><strong>New</strong> から新規作成するか、SillyTavern の Chat Completion プリセットを取り込みます。サンプリング項目は無視され、モデル設定で行うよう案内されます。</li><li>初期状態では <strong>デフォルト</strong> の印が付いた 1 件だけです。編集も削除もできません。</li><li>行のメニューから、先頭へ移動、デフォルトに設定、編集、複製、書き出し、削除ができます。</li><li>新規と複製は先に編集画面へ進み、<strong>Save</strong> したあと一覧に出ます。</li></ol><h2 id="プリセットを編集" tabindex="-1">プリセットを編集 <a class="header-anchor" href="#プリセットを編集" aria-label="Permalink to &quot;プリセットを編集&quot;">​</a></h2><ul><li><strong>Name</strong> は必須です。</li><li><strong>Basic prompts</strong> ではペルソナ、説明、性格、シナリオ、例示チャットの開始、新しいチャットの開始、ロアブックを変えられます。</li><li><strong>Prompts</strong> は検索できます。長押しで並べ替えます。スイッチがオンの項目は通常送信に使われ、オフは未使用のままで注入されません。</li><li><strong>Add</strong> で新しいプロンプトを作ります。カスタム項目は編集、複製、削除できます。組み込み項目は名前と内容だけです。</li></ul><p>キャラカードのメインプロンプトと履歴後指示は、プリセットの対応項目より優先されます。シナリオ本文は、チャット設定、キャラカード、Basic prompts の平文、の順です。</p><p>続行、再生成、スマート返信はこのプリセットを読みません。通常の送信だけが、一覧の順で組み立てます。</p><h2 id="新しいプロンプト" tabindex="-1">新しいプロンプト <a class="header-anchor" href="#新しいプロンプト" aria-label="Permalink to &quot;新しいプロンプト&quot;">​</a></h2><ol><li><strong>Name</strong> は必須です。</li><li><strong>Role</strong> の初期値は SYSTEM で、変更できます。</li><li><strong>Injection position</strong> を <strong>Relative</strong> にすると、一覧のその位置に入ります。<strong>In-chat</strong> のときだけ <strong>Injection depth</strong> が出て、その深さで履歴に入ります。</li><li><strong>Content</strong> にプロンプトを書きます。マクロも使えます。</li><li><strong>Save</strong> でプリセット編集に戻ります。</li></ol><h2 id="このチャットだけ" tabindex="-1">このチャットだけ <a class="header-anchor" href="#このチャットだけ" aria-label="Permalink to &quot;このチャットだけ&quot;">​</a></h2><p>経路：対話 → <strong>チャット設定</strong> → モデル → <strong>Presets</strong>。</p><p>初期状態はデフォルトのプリセットに従います。オフにすると、このチャットだけ別のプリセットを選べます。</p><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="./model-link">モデル接続</a>：サンプリングはモデル設定</li><li><a href="./persona">ペルソナ</a> · <a href="./lorebook">ワールドブック</a>：Basic prompts から参照できます</li></ul>',19)])])}const v=i(p,[["render",g]]);export{P as __pageData,v as default};
